function renderSection(section, tag = "h3") {
  const items = section.items.map((item) => "<li>".concat(item, "</li>")).join("\n");
  return '\n    <section class="help-section">\n      <'.concat(tag, ">").concat(section.title, "</").concat(tag, ">\n      <ul>").concat(items, "</ul>\n    </section>");
}
